 need(ports==6,"six exact initial ports");var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!original.contains(e.getName()))fresh.add(e.getName());need(fresh.equals(Set.of(N+".class")),"one stateless helper only");var helper=FreezeSourceTargetDelta.read(jar,N);need(helper.fields.size()==1&&helper.fields.get(0).desc.equals("Ljava/lang/Object;")&&(helper.fields.get(0).access&ACC_PRIVATE)!=0,"only private actor-free denial marker");for(var m:helper.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW)need(t.desc.equals("java/lang/Object"),"no task/frame/actor ownership");if(n instanceof MethodInsnNode call)need(!Set.of("getConnection","executeQuery","executeUpdate","schedule","scheduleAtFixedRate","nextInt","heal","damage","setChargeCount","nativePlayerActionLock","runPairOrdered","commitPair","token").contains(call.name)||call.name.equals("token")&&(call.owner.equals(D)||call.owner.equals(MAT)),"no SQL/RNG/HP/cost/worker/player-lock ownership");}
